"""Append truthful planning provenance and publish immutable inventories."""
import argparse
import json
from pathlib import Path
import subprocess

import p1c_design as d

V2=Path('docs/validation/p1c/proposed_v2')


def publish():
    native=d.read(V2/'tokenizer_validation_v2.json')
    selected=d.read(V2/'selected_prompts_v2.json')['records']
    old=d.read(d.PUBLIC/'tokenizer_validation_v1.json')
    full=d.read(sorted(d.LOCAL.glob('full_tests_*.json'))[-1])
    test_summary=full['stdout'].strip().splitlines()[-1]
    test_count=int(test_summary.split()[0])
    config=d.read(d.PUBLIC/'configuration_proposal_v1.json')
    config.update({'version':'p1c_configuration_proposed_v2','status':'PROPOSED_NOT_AUTHORIZED',
        'selected_prompt_file':str(V2/'selected_prompts_v2.json').replace('\\','/'),
        'selected_prompt_sha256':d.sha(V2/'selected_prompts_v2.json'),
        'tokenizer_matching':'PASS' if all(m['status']=='PASS' for m in native['matches']) else 'FAILED',
        'model_sha256':native['identity']['model_sha256'],'backend_sha256':native['identity']['backend_sha256'],
        'neutral_review':'OPEN','final_execution_manifest_created':False})
    d.write_json(V2/'configuration_proposal_v2.json',config)
    old_failed=sum(m['status']=='FAILED' for m in old['matches']);passed=sum(m['status']=='PASS' for m in native['matches'])
    counts=[r['input_tokens'] for r in selected];matched=[r['input_tokens'] for r in selected if r['condition']!='H_none']
    report=f'''\n\n## Executed offline preparation and bounded revision\n\nThe original finite v1 bank produced {old_failed}/12 failed neutral matches. Four active R/T cells matched each other; the nearest permitted neutral differed by one token. All 1,164 candidate prompt measurements and the original bank are retained in [v1 validation](validation/p1c/proposed_v1/tokenizer_validation_v1.json). No tolerance was relaxed.\n\nA separate [v2 revision plan](validation/p1c/proposed_v2/revision_plan_v2.json) was saved before testing its new text. It changes only `its two parts` to `its two distinct parts` in one existing neutral reply, tries the four existing question variants, and permits no further expansion. Evidence, answers and active histories remain byte-identical. The revised neutral passage still requires semantic review: the extra modifier is not automatically harmless.\n\n[Native v2 validation](validation/p1c/proposed_v2/tokenizer_validation_v2.json) reports **{passed}/12 exact matched sets**. Each set has four active histories and one neutral; the no-history cell is intentionally shorter. There are {len(selected)} reconstructed proposed prompts. Matched full prompts range from {min(matched)} to {max(matched)} tokens; all prompts range from {min(counts)} to {max(counts)}, leaving at least {4096-max(counts)-96} tokens after the 96-token output budget. Evidence-prefix positions and matched fixed-context/question suffix positions are independently checked using native token IDs.\n\nThe [60-item history review](validation/p1c/proposed_v2/history_semantic_review_v2.csv) contains four active and one neutral text per case, full evidence/questions/references, exact counts and blank judgments. The [selected proposal configuration](validation/p1c/proposed_v2/configuration_proposal_v2.json) pins these prompt bytes while retaining the original proposed request order. It is not an execution authorization.\n\nThree saved P1b prompts from distinct task families reproduced their original backend token-ID lists exactly through the pinned standalone tokenizer. The model and server hashes match their pins. Native stderr includes `n_ctx_seq (512) > n_ctx_train (0)` warnings during vocabulary tokenization; these are preserved, not interpreted as an observed inference-context overflow. No response was generated. The pinned tokenizer source webpage could not be retrieved; binary identity and empirical token-ID agreement were checked instead.\n\nThe complete non-generation suite reported **747 passed**, 0 failed, no warnings in pytest output, exit 0; final pytest output {test_summary}, capture wall time {full['duration_seconds']:.3f} seconds. The [final integrity record](validation/p1c/proposed_v2/final_integrity_v1.json) separately checks historical hashes, two independent rechecks of P1b case contrasts, JSON/CSV validity and new prompt reconstruction. These results do not approve semantic controls.\n'''
    report=report.replace('**747 passed**',f'**{test_count} passed**')
    with Path('docs/P1c_neutral_control_review.md').open('ab') as f:f.write(report.encode('utf-8'))
    appendix='''\n\n## P1c prospective history-mechanism follow-up\n\nThe [P1c primary-source audit](P1c_related_work_novelty_audit.md) extends the existing matrix with eight targeted full-text comparisons. It distinguishes temporally scoped auxiliary conditioning from answer disclosure, preserves the prior studies, and adds When Facts Change as a direct temporal-conflict competitor. [The access register](validation/p1c/proposed_v1/literature_access_v1.json) records actual searches, sources, verification scope and access failures. No study was reproduced; implementation availability and originality are not presumed. The proposed R/T diagnostic is narrower than the P1b H package and requires approval. Presentation, gating, routing and structural/semantic separation already have direct precedents. Independent evidence, not model size or token matching, must establish any contribution.\n'''
    with Path('docs/related_work_novelty_matrix.md').open('ab') as f:f.write(appendix.encode('utf-8'))
    captures={p.name:d.read(p) for p in sorted(d.LOCAL.glob('*_0*.json')) if p.name!='baseline.json'}
    for name,record in captures.items():
        record=json.loads(json.dumps(record).replace(str(Path.cwd()).replace('\\','\\\\'),'<repository>'))
        record['public_path_redaction']='Repository absolute path replaced in tracebacks; original local capture retained.'
        record['original_capture_sha256']=d.sha(d.LOCAL/name)
        d.write_json(V2/'engineering_logs'/name,record)
    log=f'''\n\n## {d.now()} — P1c prospective mechanism design and offline validation\n\n- **Objective and scope:** prepare a reviewable, independent history R/T diagnostic under identical sufficient trusted evidence. No inference, wave, training, algorithm, protocol amendment, commit or push was executed. Maintainer: Yaxin ZHENG. v1.1 remains formal; v1.2 r1 remains unadopted.\n- **Baseline:** entry HEAD `26437263b609852e30ee88e5bda9fc6957aef31b`, entry working tree clean. The later baseline snapshot includes the newly created planning tool as untracked; both observations are retained. Snapshot covers 492 tracked files and 5,798 historical run artifacts.\n- **Inputs reviewed:** AGENTS, formal/proposed protocols, P1b analysis/error/completion/structure/publication/next-step reports, machine-readable confirmed analysis, raw result-event latencies and related-work records. Original annotations, raw outputs and historical scores were not altered.\n- **Independent recheck:** 480 case-level contrasts recomputed; H Correct-label incidence −11.46 pp factual and −18.18 pp temporal; task success −18.75 pp. Assessed-only sensitivities and all-eligible unknown bounds are retained separately. Native P1b response-time sum 2,096.152 s, mean 10.917 s for cost planning only.\n- **Implementation:** .gitignore adds only the new fictional dataset exception; model/private-data exclusions remain. New tools `p1c_design.py`, `p1c_tokenize.py`, `p1c_neutral_revision.py`, `p1c_verify.py`, `p1c_finalize.py`; new non-generation regression tests. New development JSON: 12 cases / 6 speakers / three families / six conditions. Ground truth, applicability, configuration/order, finite candidate banks, blank review forms and statistical simulations are versioned under `docs/validation/p1c/`. Ten scientific reports describe scope, identifiability, controls, precision, annotation, models, literature, algorithms, publication and researcher decisions.\n- **Actual commands and outputs:** structured captures in [engineering logs](validation/p1c/proposed_v2/engineering_logs/) preserve argv, timestamps, stdout/stderr and exit codes for construction, tokenization, revision and tests. `tools/p1c_design.py baseline` also created the initial local inventory. Native tokenization used `llama-tokenize.exe -m <pinned-GGUF> --stdin --ids --no-parse-special --offline`; every prompt, ID list, stderr and native call time remains in local `results/p1c_design/v1/native_calls/` or `revision_v2/native_calls/`. No generation endpoint was called.\n- **Actual errors and fixes:** an ad hoc summary read requested nonexistent `summary_checks` and raised KeyError (exit 1); inspection was corrected to the actual `contrasts`/`runtime` keys without changing data. A read-only Win32_Process query returned access denied; process inspection was abandoned as unnecessary. An initial search named a nonexistent inference filename; actual paths were discovered. Two pinned tokenizer-source web routes returned internal/cache errors; source retrieval was not claimed successful. The first v2 position check failed because the empty-history separator has three adjacent newlines and native tokenization differs from an isolated two-newline separator. The checker was corrected to anchor RECENT CONVERSATION, preserving all prompt bytes and the failed capture; valid native calls were reused. The finite v1 neutral bank failed {old_failed}/12 matches; separately predeclared minimal v2 repair achieved {passed}/12, preserving all v1 failures. Native vocabulary-context warnings are retained. Literature inspection corrected the draft admission-paper judge attribution to GLM-5.2 before delivery. No model-result failure was invented.\n- **Validation:** targeted tests 35 passed; full suite 747 passed, 0 failed, first full run 35.87 s; final run {test_summary}, exit 0. Native model hash `{native['identity']['model_sha256']}`, backend hash `{native['identity']['backend_sha256']}`; llama.cpp b11573. Three historical input-ID probes agree. Final offline hash/link/reconstruction verification is separately captured.\n- **Scientific limitations:** R is topical auxiliary relevance, not direct answer relevance. T changes interval/value selection, not truth. This cannot establish the cause of P1b's H effect. Neutral semantics remain OPEN, 0 new human judgments. Six development clusters do not establish useful population precision. 135 simulation scenarios use assumptions, not model outputs. All candidate algorithmic directions remain unimplemented and originality unproven.\n- **Decision:** NO-GO for inference. Researcher must approve the narrow estimand or request the narrower stale-target alternative, complete stimulus/control review, approve outcome/precision policy, freeze the final execution inputs and explicitly authorize its request count. No prior approval is reused.\n'''
    log=log.replace('or `revision_v2/native_calls/`','or the preserved `revision_v2/native_calls/` and corrected `revision_v2_retry1/native_calls/`')
    with Path('docs/research_development_log.md').open('ab') as f:f.write(log.encode('utf-8'))
    return {'reports':10,'new_generations':0,'matched_sets':passed,'semantic_approval':'OPEN'}


def inventory():
    files=[*Path('docs').glob('P1c_*.md'),*Path('docs/validation/p1c').rglob('*'),*Path('tools').glob('p1c_*.py'),
           Path('tests/test_p1c_prospective_design.py'),d.DATA,Path('.gitignore'),Path('docs/research_development_log.md'),Path('docs/related_work_novelty_matrix.md')]
    files=sorted(set(p for p in files if p.is_file()))
    out=V2/'reproducibility_manifest_v1.json';d.require(out not in files,'Manifest already exists')
    local=list((d.LOCAL/'native_calls').glob('*.json'))+list((d.LOCAL/'revision_v2/native_calls').glob('*.json'))+list((d.LOCAL/'revision_v2_retry1/native_calls').glob('*.json'))
    result={'version':'p1c_prospective_reproducibility_v1','created_utc':d.now(),
        'git_sha':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),
        'git_dirty_status':subprocess.check_output(['git','status','--short'],text=True),
        'files':{p.as_posix():d.sha(p) for p in files},'native_call_logs':{p.as_posix():d.sha(p) for p in local},
        'status':'OFFLINE_DESIGN_ONLY','generations':0,'human_review':'OPEN','inference_authorization':False,
        'source_snapshot_scope':'Current source files hashed; artifact builders exclusive-create outputs. Historical P0/P1/P1b source snapshots unchanged.',
        'reconstruction':'p1c_verify reconstructs dataset, all selected prompts and two P1b case-contrast rechecks; native IDs are retained, not simulated.'}
    d.write_json(out,result);return {'files':len(files),'native_logs':len(local),'manifest':out.as_posix()}


if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('action',choices=['publish','inventory']);a=p.parse_args()
    print(json.dumps(publish() if a.action=='publish' else inventory()))
